1	//! 명령행(계약 1절). 기준 구현이 쓰는 Python 3.12 argparse 의 해석 순서를 그대로 따른다
2	//! (_parse_known_args, _parse_optional, _get_option_tuples, consume_optional, consume_positionals).
3	//! 접두어 약어(--to, --js), --top 반복 시 마지막 값, '--' 처리, 음수 모양 위치 인자가 여기에 들어 있다.
4	
5	use std::ffi::OsString;
6	
7	use crate::text::is_decimal;
8	
9	pub const USAGE: &str = "usage: wordfreq [-h] [--top TOP] [--json] file\n";
10	
11	pub const HELP: &str = "usage: wordfreq [-h] [--top TOP] [--json] file
12	
13	Count word frequencies.
14	
15	positional arguments:
16	  file        UTF-8 text file
17	
18	options:
19	  -h, --help  show this help message and exit
20	  --top TOP   number of words (default 10)
21	  --json      print JSON instead of text
22	";
23	
24	const DEFAULT_TOP: usize = 10;
25	
26	/// --top 이 이보다 큰 자릿수면 그냥 "아주 큰 수"로 본다 (기준 구현의 MAX_TOP_DIGITS)
27	const MAX_TOP_DIGITS: usize = 18;
28	
29	#[derive(Debug, PartialEq, Eq)]
30	pub struct Args {
31	    pub file: OsString,
32	    pub top: usize,
33	    pub json: bool,
34	}
35	
36	#[derive(Debug, PartialEq, Eq)]
37	pub enum Command {
38	    Run(Args),
39	    Help,
40	}
41	
42	/// 인자 오류. 메시지 내용은 계약상 비교하지 않는다.
43	#[derive(Debug, PartialEq, Eq)]
44	pub struct UsageError(pub String);
45	
46	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
47	enum Action {
48	    Help,
49	    Top,
50	    Json,
51	}
52	
53	impl Action {
54	    /// 이 옵션이 받는 값의 수 (help·json 은 0, top 은 1)
55	    fn nargs(self) -> usize {
56	        match self {
57	            Action::Top => 1,
58	            Action::Help | Action::Json => 0,
59	        }
60	    }
61	}
62	
63	/// argparse 에 등록된 순서대로
64	const OPTIONS: [(&str, Action); 4] = [
65	    ("-h", Action::Help),
66	    ("--help", Action::Help),
67	    ("--top", Action::Top),
68	    ("--json", Action::Json),
69	];
70	
71	fn lookup(option: &str) -> Option<Action> {
72	    OPTIONS
73	        .iter()
74	        .find(|(name, _)| *name == option)
75	        .map(|&(_, action)| action)
76	}
77	
78	/// argparse 의 sep: None, '' (붙여 쓴 짧은 옵션), '='
79	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
80	enum Sep {
81	    None,
82	    Empty,
83	    Equals,
84	}
85	
86	#[derive(Debug, Clone)]
87	struct OptionTuple {
88	    action: Option<Action>,
89	    option_string: String,
90	    sep: Sep,
91	    explicit_arg: Option<String>,
92	}
93	
94	impl OptionTuple {
95	    fn new(action: Option<Action>, option_string: &str, sep: Sep, explicit: Option<&str>) -> Self {
96	        OptionTuple {
97	            action,
98	            option_string: option_string.to_string(),
99	            sep,
100	            explicit_arg: explicit.map(str::to_string),
101	        }
102	    }
103	}
104	
105	/// '^-\d+$|^-\d*\.\d+$' (Python re: $ 는 끝의 '\n' 하나 앞에서도 맞는다)
106	fn looks_like_negative_number(arg: &str) -> bool {
107	    let Some(rest) = arg.strip_prefix('-') else {
108	        return false;
109	    };
110	    let body = rest.strip_suffix('\n').unwrap_or(rest);
111	    let all_digits = |s: &str| s.chars().all(is_decimal);
112	    match body.split_once('.') {
113	        None => !body.is_empty() && all_digits(body),
114	        Some((int, frac)) => all_digits(int) && !frac.is_empty() && all_digits(frac),
115	    }
116	}
117	
118	fn get_option_tuples(arg: &str) -> Vec<OptionTuple> {
119	    let mut result = Vec::new();
120	    if arg.starts_with("--") {
121	        let (prefix, sep, explicit) = match arg.split_once('=') {
122	            Some((prefix, explicit)) => (prefix, Sep::Equals, Some(explicit)),
123	            None => (arg, Sep::None, None),
124	        };
125	        for &(name, action) in &OPTIONS {
126	            if name.starts_with(prefix) {
127	                result.push(OptionTuple::new(Some(action), name, sep, explicit));
128	            }
129	        }
130	    } else {
131	        // 앞의 두 글자('-' 와 그 다음 글자)가 짧은 옵션, 나머지는 붙여 쓴 값
132	        let split = arg.char_indices().nth(2).map_or(arg.len(), |(i, _)| i);
133	        let (short, short_explicit) = arg.split_at(split);
134	        for &(name, action) in &OPTIONS {
135	            if name == short {
136	                result.push(OptionTuple::new(
137	                    Some(action),
138	                    name,
139	                    Sep::Empty,
140	                    Some(short_explicit),
141	                ));
142	            } else if name.starts_with(arg) {
143	                result.push(OptionTuple::new(Some(action), name, Sep::None, None));
144	            }
145	        }
146	    }
147	    result
148	}
149	
150	/// None 이면 위치 인자
151	fn parse_optional(arg: &str) -> Result<Option<OptionTuple>, UsageError> {
152	    if !arg.starts_with('-') {
153	        return Ok(None);
154	    }
155	    if let Some(action) = lookup(arg) {
156	        return Ok(Some(OptionTuple::new(Some(action), arg, Sep::None, None)));
157	    }
158	    if arg.chars().count() == 1 {
159	        return Ok(None);
160	    }
161	    if let Some((option, explicit)) = arg.split_once('=') {
162	        if let Some(action) = lookup(option) {
163	            return Ok(Some(OptionTuple::new(
164	                Some(action),
165	                option,
166	                Sep::Equals,
167	                Some(explicit),
168	            )));
169	        }
170	    }
171	    let mut tuples = get_option_tuples(arg);
172	    if tuples.len() > 1 {
173	        let names: Vec<&str> = tuples.iter().map(|t| t.option_string.as_str()).collect();
174	        return Err(UsageError(format!(
175	            "ambiguous option: {arg} could match {}",
176	            names.join(", ")
177	        )));
178	    }
179	    if let Some(tuple) = tuples.pop() {
180	        return Ok(Some(tuple));
181	    }
182	    if looks_like_negative_number(arg) || arg.contains(' ') {
183	        return Ok(None);
184	    }
185	    Ok(Some(OptionTuple::new(None, arg, Sep::None, None)))
186	}
187	
188	/// 계약 1절: ASCII 숫자만. 앞의 0 은 무시, 0 은 오류, 18자리를 넘으면 아주 큰 수
189	fn positive_int(value: &str) -> Result<usize, UsageError> {
190	    if value.is_empty() || !value.bytes().all(|b| b.is_ascii_digit()) {
191	        return Err(UsageError(format!(
192	            "argument --top: not an integer: {value}"
193	        )));
194	    }
195	    let digits = value.trim_start_matches('0');
196	    if digits.is_empty() {
197	        return Err(UsageError(format!(
198	            "argument --top: must be at least 1: {value}"
199	        )));
200	    }
201	    if digits.len() > MAX_TOP_DIGITS {
202	        return Ok(usize::MAX);
203	    }
204	    let n = digits
205	        .bytes()
206	        .fold(0u64, |acc, b| acc * 10 + u64::from(b - b'0'));
207	    Ok(usize::try_from(n).unwrap_or(usize::MAX))
208	}
209	
210	struct Parser<'a> {
211	    raw: &'a [OsString],
212	    strings: Vec<String>,
213	    pattern: Vec<u8>,
214	    options: Vec<Option<OptionTuple>>,
215	    file: Option<OsString>,
216	    file_pending: bool,
217	    top: usize,
218	    json: bool,
219	    extras: Vec<String>,
220	}
221	
222	/// 옵션 처리 결과: 다음 위치, 또는 도움말 출력
223	enum Step {
224	    Next(usize),
225	    Help,
226	}
227	
228	impl Parser<'_> {
229	    /// 위치 인자 file 의 패턴 '(-*A-*)' 를 start 에서 맞춰 본다
230	    fn consume_positionals(&mut self, start: usize) -> usize {
231	        if !self.file_pending {
232	            return start;
233	        }
234	        let rest = &self.pattern[start..];
235	        let leading = rest.iter().take_while(|&&p| p == b'-').count();
236	        if rest.get(leading) != Some(&b'A') {
237	            return start;
238	        }
239	        let trailing = rest[leading + 1..]
240	            .iter()
241	            .take_while(|&&p| p == b'-')
242	            .count();
243	        let end = start + leading + 1 + trailing;
244	        // 첫 '--' 하나를 빼면 값 하나가 남는다
245	        let mut values: Vec<usize> = (start..end).collect();
246	        if let Some(pos) = values.iter().position(|&i| self.strings[i] == "--") {
247	            values.remove(pos);
248	        }
249	        if let Some(&i) = values.first() {
250	            self.file = Some(self.raw[i].clone());
251	        }
252	        self.file_pending = false;
253	        end
254	    }
255	
256	    fn take_action(
257	        &mut self,
258	        action: Action,
259	        value: Option<&str>,
260	    ) -> Result<Option<Step>, UsageError> {
261	        match action {
262	            Action::Help => return Ok(Some(Step::Help)),
263	            Action::Json => self.json = true,
264	            Action::Top => self.top = positive_int(value.unwrap_or_default())?,
265	        }
266	        Ok(None)
267	    }
268	
269	    fn consume_optional(&mut self, start: usize) -> Result<Step, UsageError> {
270	        let Some(tuple) = self.options[start].clone() else {
271	            return Ok(Step::Next(start + 1));
272	        };
273	        let OptionTuple {
274	            action,
275	            mut option_string,
276	            mut sep,
277	            mut explicit_arg,
278	        } = tuple;
279	        let mut action = action;
280	        let mut actions: Vec<(Action, Option<String>)> = Vec::new();
281	        let stop;
282	        loop {
283	            let Some(act) = action else {
284	                self.extras.push(self.strings[start].clone());
285	                return Ok(Step::Next(start + 1));
286	            };
287	            if let Some(explicit) = explicit_arg.take() {
288	                let short = !option_string[1..].starts_with('-');
289	                if act.nargs() == 0 && short && !explicit.is_empty() {
290	                    if sep == Sep::Equals || explicit.starts_with('-') {
291	                        return Err(UsageError(format!(
292	                            "argument {option_string}: ignored explicit argument '{explicit}'"
293	                        )));
294	                    }
295	                    actions.push((act, None));
296	                    let mut chars = explicit.chars();
297	                    let first = chars.next().unwrap_or_default();
298	                    let rest = chars.as_str();
299	                    option_string = format!("-{first}");
300	                    if let Some(next) = lookup(&option_string) {
301	                        action = Some(next);
302	                        if rest.is_empty() {
303	                            sep = Sep::None;
304	                            explicit_arg = None;
305	                        } else if let Some(after) = rest.strip_prefix('=') {
306	                            sep = Sep::Equals;
307	                            explicit_arg = Some(after.to_string());
308	                        } else {
309	                            sep = Sep::Empty;
310	                            explicit_arg = Some(rest.to_string());
311	                        }
312	                    } else {
313	                        self.extras.push(format!("-{explicit}"));
314	                        stop = start + 1;
315	                        break;
316	                    }
317	                } else if act.nargs() == 1 {
318	                    actions.push((act, Some(explicit)));
319	                    stop = start + 1;
320	                    break;
321	                } else {
322	                    return Err(UsageError(format!(
323	                        "argument {option_string}: ignored explicit argument '{explicit}'"
324	                    )));
325	                }
326	            } else {
327	                let next = start + 1;
328	                let mut value = None;
329	                if act.nargs() == 1 {
330	                    if self.pattern.get(next) != Some(&b'A') {
331	                        return Err(UsageError(format!(
332	                            "argument {option_string}: expected one argument"
333	                        )));
334	                    }
335	                    value = Some(self.strings[next].clone());
336	                }
337	                actions.push((act, value));
338	                stop = next + act.nargs();
339	                break;
340	            }
341	        }
342	        for (act, value) in actions {
343	            if let Some(step) = self.take_action(act, value.as_deref())? {
344	                return Ok(step);
345	            }
346	        }
347	        Ok(Step::Next(stop))
348	    }
349	
350	    fn run(&mut self) -> Result<Step, UsageError> {
351	        let option_indices: Vec<usize> = (0..self.options.len())
352	            .filter(|&i| self.pattern[i] == b'O')
353	            .collect();
354	        let mut start = 0;
355	        while let Some(&next) = option_indices.iter().find(|&&i| i >= start) {
356	            if start != next {
357	                let end = self.consume_positionals(start);
358	                if end > start {
359	                    start = end;
360	                    continue;
361	                }
362	            }
363	            if start != next {
364	                self.extras.extend_from_slice(&self.strings[start..next]);
365	                start = next;
366	            }
367	            match self.consume_optional(start)? {
368	                Step::Next(stop) => start = stop,
369	                Step::Help => return Ok(Step::Help),
370	            }
371	        }
372	        let stop = self.consume_positionals(start);
373	        self.extras.extend_from_slice(&self.strings[stop..]);
374	        Ok(Step::Next(stop))
375	    }
376	}
377	
378	/// args 는 프로그램 이름을 뺀 인자들
379	pub fn parse(args: &[OsString]) -> Result<Command, UsageError> {
380	    // 옵션 판단과 오류 메시지에는 손실 변환한 문자열을 쓰고, 파일 이름은 원래 바이트를 그대로 쓴다
381	    let strings: Vec<String> = args
382	        .iter()
383	        .map(|a| a.to_string_lossy().into_owned())
384	        .collect();
385	    let mut pattern = Vec::with_capacity(strings.len());
386	    let mut options = Vec::with_capacity(strings.len());
387	    let mut after_double_dash = false;
388	    for arg in &strings {
389	        if after_double_dash {
390	            pattern.push(b'A');
391	            options.push(None);
392	        } else if arg == "--" {
393	            after_double_dash = true;
394	            pattern.push(b'-');
395	            options.push(None);
396	        } else {
397	            let tuple = parse_optional(arg)?;
398	            pattern.push(if tuple.is_some() { b'O' } else { b'A' });
399	            options.push(tuple);
400	        }
401	    }
402	    let mut parser = Parser {
403	        raw: args,
404	        strings,
405	        pattern,
406	        options,
407	        file: None,
408	        file_pending: true,
409	        top: DEFAULT_TOP,
410	        json: false,
411	        extras: Vec::new(),
412	    };
413	    if let Step::Help = parser.run()? {
414	        return Ok(Command::Help);
415	    }
416	    let Some(file) = parser.file else {
417	        return Err(UsageError(
418	            "the following arguments are required: file".to_string(),
419	        ));
420	    };
421	    if !parser.extras.is_empty() {
422	        return Err(UsageError(format!(
423	            "unrecognized arguments: {}",
424	            parser.extras.join(" ")
425	        )));
426	    }
427	    Ok(Command::Run(Args {
428	        file,
429	        top: parser.top,
430	        json: parser.json,
431	    }))
432	}
433	
434	#[cfg(test)]
435	mod tests {
436	    use super::*;
437	
438	    fn parse_strs(args: &[&str]) -> Result<Command, UsageError> {
439	        let args: Vec<OsString> = args.iter().map(OsString::from).collect();
440	        parse(&args)
441	    }
442	
443	    fn run(file: &str, top: usize, json: bool) -> Result<Command, UsageError> {
444	        Ok(Command::Run(Args {
445	            file: OsString::from(file),
446	            top,
447	            json,
448	        }))
449	    }
450	
451	    #[test]
452	    fn basic_forms() {
453	        assert_eq!(parse_strs(&["a.txt"]), run("a.txt", 10, false));
454	        assert_eq!(
455	            parse_strs(&["--top", "3", "a.txt", "--json"]),
456	            run("a.txt", 3, true)
457	        );
458	        assert_eq!(parse_strs(&["a.txt", "--top=1"]), run("a.txt", 1, false));
459	        assert_eq!(
460	            parse_strs(&["a.txt", "--to", "2", "--js"]),
461	            run("a.txt", 2, true)
462	        );
463	        assert_eq!(parse_strs(&["a.txt", "--t=2"]), run("a.txt", 2, false));
464	        assert!(parse_strs(&["a.txt", "--top", "0", "--top", "2"]).is_err());
465	        assert_eq!(
466	            parse_strs(&["a.txt", "--top", "1", "--top", "2"]),
467	            run("a.txt", 2, false)
468	        );
469	    }
470	
471	    #[test]
472	    fn positional_edge_cases() {
473	        assert_eq!(parse_strs(&["-"]), run("-", 10, false));
474	        assert_eq!(parse_strs(&["--", "-x"]), run("-x", 10, false));
475	        assert_eq!(parse_strs(&["--", "--"]), run("--", 10, false));
476	        assert_eq!(parse_strs(&["a.txt", "--"]), run("a.txt", 10, false));
477	        assert_eq!(parse_strs(&["-5"]), run("-5", 10, false));
478	        assert_eq!(parse_strs(&["-.5"]), run("-.5", 10, false));
479	        assert_eq!(parse_strs(&["-5\n"]), run("-5\n", 10, false));
480	        assert_eq!(parse_strs(&["-x y"]), run("-x y", 10, false));
481	        assert_eq!(parse_strs(&[""]), run("", 10, false));
482	        assert!(parse_strs(&["a.txt", "--json", "--"]).is_err());
483	        assert!(parse_strs(&["a.txt", "b.txt"]).is_err());
484	        assert!(parse_strs(&["-x.txt"]).is_err());
485	        assert!(parse_strs(&[]).is_err());
486	        assert!(parse_strs(&["--"]).is_err());
487	    }
488	
489	    #[test]
490	    fn help_and_errors() {
491	        assert_eq!(parse_strs(&["-h"]), Ok(Command::Help));
492	        assert_eq!(parse_strs(&["--he"]), Ok(Command::Help));
493	        assert_eq!(parse_strs(&["-hx"]), Ok(Command::Help));
494	        assert_eq!(parse_strs(&["--bogus", "-h"]), Ok(Command::Help));
495	        assert!(parse_strs(&["-h="]).is_err());
496	        assert!(parse_strs(&["--top", "0", "-h"]).is_err());
497	        assert!(parse_strs(&["-h", "--=x"]).is_err());
498	        assert!(parse_strs(&["a.txt", "--json=1"]).is_err());
499	        assert!(parse_strs(&["a.txt", "--top"]).is_err());
500	        assert!(parse_strs(&["a.txt", "--top", "--json"]).is_err());
501	    }
502	
503	    #[test]
504	    fn top_values() {
505	        assert_eq!(positive_int("007"), Ok(7));
506	        assert_eq!(
507	            positive_int("999999999999999999"),
508	            Ok(999_999_999_999_999_999)
509	        );
510	        assert_eq!(positive_int("1000000000000000000"), Ok(usize::MAX));
511	        assert_eq!(positive_int(&"9".repeat(5000)), Ok(usize::MAX));
512	        for bad in [
513	            "", "0", "000", "+3", " 3", "3 ", "1_0", "２", "٣", "-1", "abc",
514	        ] {
515	            assert!(positive_int(bad).is_err(), "{bad:?}");
516	        }
517	    }
518	}
519

